import{_ as a,o as t,c as r,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph Performance Meeting 2021-10-21","description":"","frontmatter":{"title":"Ceph Performance Meeting 2021-10-21","date":"2021-10-21T00:00:00.000Z","updated":"2021-10-22T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","PR审查","库存管理"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Performance_Meeting_2021-10-21.md","filePath":"posts/2021/Ceph_Performance_Meeting_2021-10-21.md","lastUpdated":1780459816000}'),l={name:"posts/2021/Ceph_Performance_Meeting_2021-10-21.md"};function n(o,e,s,P,d,c){return t(),r("div",null,[...e[0]||(e[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>新PR讨论</strong>：会议讨论了一个关于backfill和recovery性能的新PR，该PR针对新OSD从主OSD进行完整复制的情况，通过PG日志进行恢复，比传统的recovery更快。该PR由用户“gun”提交，Mia将进行审查。</li><li><strong>已关闭的PR</strong>：会议讨论了四个已关闭的PR，包括TTL缓存、async messenger帧消息头优化、OSD压缩绕过和BlueFist fine green locking PR。BlueFist PR在测试中导致锁定失败，Adam正在处理。</li><li><strong>更新的PR</strong>：三个PR已更新，包括MDS的树移除PR和两个库D优化PR，需要重新审查。</li><li><strong>性能优化</strong>：Jeff Layton提交了内核客户端的修复，可能解决之前观察到的3GB/s瓶颈问题，Ilia将审查并进行测试，目标是达到8GB/s的性能。</li><li><strong>GDB PMP问题</strong>：GDB PMP在多线程环境下导致经典OSD崩溃，Adam开发了一个使用live unwind的新版本，速度更快但代码复杂。目前正在尝试结合lib unwind和lib dw进行优化。</li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ul><li><strong>Backfill与Recovery性能优化</strong>：会议重点讨论了新PR中提出的backfill与recovery性能优化方法。</li><li><strong>PR状态更新</strong>：回顾了已关闭和更新的PR，特别是涉及性能优化和锁定的PR。</li><li><strong>内核客户端性能瓶颈</strong>：讨论了Jeff Layton提交的修复，旨在解决内核客户端的性能瓶颈。</li><li><strong>GDB PMP的替代方案</strong>：讨论了GDB PMP的问题及其替代方案，包括Adam的新版本和结合lib unwind与lib dw的尝试。</li></ul><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li><strong>审查新PR</strong>：Mia将审查关于backfill和recovery性能的新PR。</li><li><strong>测试性能优化</strong>：Ilia将审查并测试Jeff Layton提交的内核客户端修复。</li><li><strong>继续优化GDB PMP替代方案</strong>：继续探索和优化GDB PMP的替代方案，结合lib unwind和lib dw。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>审查和测试PR</strong>：继续审查和测试所有相关的PR，确保代码质量和性能。</li><li><strong>性能测试</strong>：进行详细的性能测试，特别是内核客户端的修复和GDB PMP的替代方案。</li><li><strong>代码优化</strong>：持续优化代码，特别是涉及锁定的部分和性能瓶颈的解决。</li></ul><h3 id="结束语" tabindex="-1">结束语 <a class="header-anchor" href="#结束语" aria-label="Permalink to &quot;结束语&quot;">​</a></h3><p>会议在讨论了各项PR的状态和性能优化措施后结束，团队成员将继续跟进相关工作，确保项目的稳定性和性能提升。</p>',11)])])}const u=a(l,[["render",n]]);export{h as __pageData,u as default};
